@pytest.mark.parametrize('back', [False, True]) @pytest.mark.parametrize('fault', [None, 'thin', 'changed_current', 'wrong_ground_face']) def test_long_translation_is_not_long_routing_or_relaxed_saved_authority(tmp_path, monkeypatch, back, fault): source, root, uid = fixture(tmp_path, monkeypatch, back=back) board = pcbnew.LoadBoard(str(source)) feed=board.FindFootprintByReference('EXISTING_FEED');feed.SetPosition(pcbnew.VECTOR2I_MM(48,10)) board.FindFootprintByReference('AMP73').Move(pcbnew.VECTOR2I_MM(34,0)) from cec_native_items import discard_items discard_items(board,[t for t in board.GetTracks()if t.GetNetname()=='/ALPHA']) at=tuple(v/1e6 for v in feed.FindPadByNumber('1').GetPosition());face=pcbnew.B_Cu if back else pcbnew.F_Cu track(board,'/ALPHA',at,(at[0]+2,12),layer=face,width=.5) track(board,'/ALPHA',(at[0]+2,12),(50,12),layer=face,width=.5) for edge in board.GetDrawings(): if edge.GetLayer() != pcbnew.Edge_Cuts: continue for get, put in ((edge.GetStart, edge.SetStart), (edge.GetEnd, edge.SetEnd)): at = get() put(pcbnew.VECTOR2I(80000000 if at.x == 30000000 else at.x, 80000000 if at.y == 30000000 else at.y)) for zone in board.Zones(): outline = pcbnew.SHAPE_POLY_SET(); outline.NewOutline() for x, y in [(1, 1), (79, 1), (79, 79), (1, 79)]: outline.Append(x*1000000, y*1000000) zone.Outline().RemoveAllContours(); zone.Outline().Append(outline) ground = board.FindNet('GND') via = pcbnew.PCB_VIA(board); via.SetNet(ground) return_x = 49 if back else 51 via.SetPosition(pcbnew.VECTOR2I_MM(return_x, 14)); via.SetWidth(900000); via.SetDrill(400000) via.SetLayerPair(pcbnew.F_Cu, pcbnew.B_Cu); board.Add(via) op.additive._ground_refill(board); op.field._save_field_snapshot(board, source) raw_source = source.read_bytes() pose = [50, 14, board.FindFootprintByReference('RENAMED_C').GetOrientationDegrees()] # Existing local requests do not silently become broad placement requests. with pytest.raises(ValueError, match='bounded_nonzero_capacitor_translation_only'): op.compile(source, footprint_uuid=uid, target_pose=pose, board_hint=str(root), max_shift_mm=32) board, q = op.compile(source, footprint_uuid=uid, target_pose=pose, board_hint=str(root), max_shift_mm=64) > assert q['pose_screen']['ok'] and q['request']['max_shift_mm'] == 64 E assert (False)
